package glitch

import data.glitch_lib

data_transmission_keywords := {"storage", "transfer", "file", "messaging", "object", "download", "upload"}
integrity_keywords := {"checksum", "integrity", "hash", "digest", "validation"}
network_keywords := {"protocol", "http", "tcp", "udp", "network"}
storage_encryption_keywords := {"encryption", "kms", "volume", "disk", "ssse"}
protocol_config_keywords := {"ssl", "tls", "version", "mode"}

contains_any(str, keywords) {
    some keyword in keywords
    regex.match(sprintf("(?i).*%s.*", [keyword]), str)
}

any_integrity_attribute(attrs) {
    some attr in attrs
    contains_any(attr.name, integrity_keywords)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    contains_any(node.type, data_transmission_keywords)
    attrs := glitch_lib.all_attributes(node)
    not any_integrity_attribute(attrs)
    result := {
        "type": "sec_no_int_check",
        "element": node,
        "path": parent.path,
        "description": "Missing integrity check in data transmission resource - CWE-353"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    contains_any(node.type, network_keywords)
    attrs := glitch_lib.all_attributes(node)
    some attr in attrs
    attr.name == "checksum_offload"
    attr.value.ir_type == "Boolean"
    attr.value.value == true
    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Checksum offload enabled - CWE-353"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    contains_any(node.type, protocol_config_keywords)
    attrs := glitch_lib.all_attributes(node)
    some attr in attrs
    (attr.name == "ssl_version" || attr.name == "tls_version")
    attr.value.ir_type == "String"
