package glitch

import data.glitch_lib

data_transfer_attrs := {"source", "destination", "file", "path", "bucket", "object", "url", "endpoint"}
integrity_attrs := {"checksum", "integrity", "digest", "md5", "sha256", "validation", "content_checksum", "validation_hash", "checksum_algorithm", "hashing_algorithm"}
network_protocol_attrs := {"protocol", "http", "tcp", "udp", "checksum_offload", "signature"}
integrity_flags := {"checksum", "integrity", "verify_mode", "disable_checksum", "ignore_integrity_errors"}
storage_encryption_attrs := {"encryption", "kms", "key", "volume", "disk", "ssse"}
integrity_prot_attrs := {"integrity_algorithm", "auth_tag", "enable_integrity"}
insecure_protocol_versions := {"tlsv1.0", "tlsv1.1", "sslv3"}
insecure_policy_attrs := {"disable_checksum", "ignore_integrity_errors", "verify_mode"}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    has_data_transfer_attr := count({attr | attr := attrs[_]; data_transfer_attrs[attr.name]}) > 0
    has_integrity_attr := count({attr | attr := attrs[_]; integrity_attrs[attr.name]}) > 0

    has_data_transfer_attr
    not has_integrity_attr

    result := {
        "type": "sec_no_int_check",
        "element": node,
        "path": parent.path,
        "description": "Data transfer resource without integrity check - Missing support for integrity check in data transfer. (CWE-353)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    has_network_attr := count({attr | attr := attrs[_]; network_protocol_attrs[attr.name]}) > 0
    has_integrity_flag := count({attr | attr := attrs[_]; integrity_flags[attr.name]}) > 0

    has_network_attr
    not has_integrity_flag

    result := {
        "type": "sec_no_int_check",
        "element": node,
        "path": parent.path,
        "description": "Network protocol configuration without integrity check - Missing support for integrity check in network protocols. (CWE-353)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    attr.name == "checksum_offload"
    attr.value.ir_type == "String"
    attr.value.value in {"enabled", "true"}

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Checksum offload enabled - Disabling checksums can lead to integrity issues. (CWE-353)"
    }
}

