package glitch

import data.glitch_lib

transfer_indicators := {
    "content_checksum", "validation_hash", "checksum_algorithm", "hashing_algorithm", "source_hash",
    "checksum_offload", "integrity_algorithm", "auth_tag", "enable_integrity"
}

integrity_indicators := {
    "checksum", "integrity", "digest", "md5", "sha256", "validation"
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr_names := {a.name | a := attrs[_]}

    has_transfer := count(attr_names & transfer_indicators) > 0
    has_integrity := count(attr_names & integrity_indicators) > 0

    has_transfer
    not has_integrity

    result := {
        "type": "sec_no_int_check",
        "element": node,
        "path": parent.path,
        "description": "Missing integrity check in data transfer - The product does not use or improperly uses an integrity check mechanism for data transmission or storage. (CWE-353)"
    }
}

